const root = $input.first().json;
const body = root.body || root;
const dcr = (((body.data||{}).analysis||{}).data_collection_results) || {};
const g = (k) => { const f = dcr[k]; if(!f) return ''; const v=(f.value!==undefined?f.value:f); return (v===null||v===undefined)?'':v; };
const name=g('full_name'); const policy=g('policy_number'); const lob=String(g('line_of_business')).toLowerCase();
const phone=g('mobile_phone')||g('phone'); const email=g('email');
const dol=g('date_of_loss'); const desc=g('loss_description'); const loc=g('loss_location');
const tp=g('third_party_involved'); const inj=g('injuries'); const amt=g('estimated_amount');
const summary=g('conversation_summary');
const caseTypeID='__CLAIM_CASETYPE__';
const label='Schaden: '+(name||'Unbekannt')+' - '+(lob||'n/a')+(policy?' - Police '+policy:'');
const d=[];
if(dol)d.push('Schadendatum '+dol);
if(loc)d.push('Ort '+loc);
if(desc)d.push(desc);
d.push('Dritte beteiligt: '+(tp===''?'k.A.':tp));
d.push('Verletzte: '+(inj===''?'k.A.':inj));
if(amt)d.push('Schaetzung '+amt);
if(phone)d.push('Tel '+phone);
if(email)d.push('Email '+email);
if(summary)d.push(summary);
d.push('via V+ Schadenmeldung');
const description=d.join('; ');
return [{ json: { caseTypeID, label, description, name, policy, lineOfBusiness: lob } }];
